  "inlineSchema": "// ------------------------------------------------------------\n// This file defines all of our database tables using Prisma ORM.\n// Prisma will translate these models into SQL tables inside our\n// Supabase PostgreSQL database.\n// ------------------------------------------------------------\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ------------------------------------------------------------\n// USERS TABLE\n// Represents every member of the tool lending library.\n// Supabase Auth will handle login/signup, but we store\n// profile details here (name, email, etc.).\n// ------------------------------------------------------------\nmodel User {\n  id    Int     @id @default(autoincrement())\n  email String  @unique // Required for login\n  name  String? // Optional profile field\n\n  // Relationships\n  listings         Listing[] // Tools this user owns\n  loans            Loan[] // Tools this user has rented\n  reviews          Review[] // Reviews written by this user\n  sentMessages     ChatMessage[] @relation(\"Sender\") // Messages this user sent\n  receivedMessages ChatMessage[] @relation(\"Receiver\") // Messages this user received\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------------\n// TOOLS TABLE\n// Represents the generic tool type (e.g., \"Cordless Drill\").\n// A tool can have many listings from different owners.\n// ------------------------------------------------------------\nmodel tools {\n  id       Int     @id @default(autoincrement())\n  name     String  @db.VarChar(255) // Tool name (required)\n  category String  @db.VarChar(255) // Category (e.g., Power Tools)\n  imageUrl String? // Optional image stored in Supabase Storage\n\n  listings Listing[] // Listings for this tool\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------------\n// LISTINGS TABLE\n// Represents a specific owner's instance of a tool.\n// Example: John's drill for $10/day.\n// ------------------------------------------------------------\nmodel Listing {\n  id Int @id @default(autoincrement())\n\n  toolId    Int\n  ownerId   Int\n  price     Float // Rental price per day\n  available Boolean @default(true) // Whether the listing is rentable\n  imageUrl  String? // Optional listing-specific photo\n\n  // Relationships\n  tool         tools         @relation(fields: [toolId], references: [id], onDelete: Cascade)\n  owner        User          @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  loans        Loan[] // Loans created for this listing\n  reviews      Review[] // Reviews written for this listing\n  chatMessages ChatMessage[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------------\n// LOANS TABLE\n// Represents an active or completed rental.\n// A loan ties together: listing + renter + dates + payment.\n// ------------------------------------------------------------\nmodel Loan {\n  id Int @id @default(autoincrement())\n\n  listingId Int\n  renterId  Int\n  startDate DateTime // When rental begins\n  endDate   DateTime // When rental ends\n  status    String   @db.VarChar(50) // \"active\", \"returned\", \"late\"\n\n  // Payment (simulated / Stripe test mode)\n  totalPrice            Decimal @default(0)\n  paymentStatus         String  @default(\"pending\") // pending | authorized | captured | failed | canceled\n  stripePaymentIntentId String?\n\n  // Relationships\n  listing   Listing   @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  renter    User      @relation(fields: [renterId], references: [id], onDelete: Cascade)\n  payments  Payment[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n}\n\n// ------------------------------------------------------------\n// REVIEWS TABLE\n// Represents feedback left by renters about a listing.\n// ------------------------------------------------------------\nmodel Review {\n  id Int @id @default(autoincrement())\n\n  listingId Int\n  userId    Int\n  rating    Int // 1–5 stars\n  comment   String? // Optional text review\n\n  // Relationships\n  listing Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------------\n// CHAT MESSAGES TABLE\n// Represents messages exchanged between owner and renter.\n// IMPORTANT: Messages only exist for ACTIVE LOANS.\n// ------------------------------------------------------------\nmodel ChatMessage {\n  id         Int      @id @default(autoincrement())\n  senderId   Int      @map(\"sender_id\")\n  receiverId Int      @map(\"receiver_id\")\n  listingId  Int      @map(\"listing_id\")\n  content    String\n  isRead     Boolean  @default(false) @map(\"is_read\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  // Relationships\n  listing  Listing @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  sender   User    @relation(\"Sender\", fields: [senderId], references: [id], onDelete: Cascade)\n  receiver User    @relation(\"Receiver\", fields: [receiverId], references: [id], onDelete: Cascade)\n\n  @@map(\"messages\")\n}\n\n// ------------------------------------------------------------\n// PAYMENT   TABLE\n// Represents tracking payments between owner and renter.\n// IMPORTANT: Tracking for tax purposes.\n// ------------------------------------------------------------\n\nmodel Payment {\n  id        Int      @id @default(autoincrement())\n  loanId    Int\n  amount    Int\n  status    String\n  createdAt DateTime @default(now())\n\n  loan Loan @relation(fields: [loanId], references: [id])\n}\n",
